<?php

namespace Database\Seeders;

use App\Models\Materiel;
use Illuminate\Database\Seeder;

/**
 * One-time import of the real inventory recorded in the legacy ISSTM site
 * (github.com/Lazy6969/ISSTM, `materiels` table of its isstm_db.sql dump) —
 * 353 real pieces of equipment across 27 lieux. Not part of the regular
 * DatabaseSeeder chain: run it explicitly once (`php artisan db:seed
 * --class=LegacyMaterielSeeder`) to populate a fresh/empty `materiels` table.
 *
 * Two cleanups versus the raw dump: the legacy's two near-duplicate "bad
 * condition" états (`mauvais` and `mauvais_etat`) are both mapped to this
 * project's single `mauvais_etat`; `ajoute_par` is left null since the
 * legacy's user ids have no equivalent in this project's `users` table.
 */
class LegacyMaterielSeeder extends Seeder
{
    public function run(): void
    {
        if (Materiel::query()->exists()) {
            $this->command?->warn('materiels already has rows — skipping the legacy import to avoid duplicates.');

            return;
        }

        foreach (self::ROWS as $row) {
            Materiel::create($row);
        }
    }

